import{fmt}from'../analytics/stats.js';import{RULES,confidence}from'../analytics/config.js';
export function strategyAnalysis({rows,formats,promotion,timing,retention,attendance,promotionTiming}){const recommendations=[];for(const [kind,analysis] of [['format',formats],['promotion',promotion],['time',timing]]){const best=analysis?.best;if(!best||best.difference<=0)continue;recommendations.push({title:`Try ${best.name}${kind==='format'?' for your next meeting':''}.`,evidence:`${best.name} averaged ${fmt(best.average)} attendees across ${best.count} meetings, ${fmt(best.difference)} above the club average.`,reason:'Test this historical association while keeping other meeting details similar. It is not a guaranteed increase.',confidence:confidence(best.count),field:analysis.field,value:best.name,source:kind==='format'?'compare_meeting_types':kind==='promotion'?'compare_promotion_channels':'compare_timing'})}
if(promotionTiming?.best?.name==='3+ days ahead'&&promotionTiming.best.difference>0){const g=promotionTiming.best;recommendations.push({title:'Test starting promotion at least three days ahead.',evidence:`Meetings promoted 3+ days ahead averaged ${fmt(g.average)} attendees across ${g.count} meetings, ${fmt(g.difference)} above the compared meetings’ average.`,reason:'Keep the format similar and measure the next few meetings. Timing may overlap with other factors.',confidence:confidence(g.count),source:'analyze_promotion_timing'})}
if(retention?.available&&retention.eligible>=5&&retention.rate<.5)recommendations.push({title:'Test a newcomer welcome activity.',evidence:`${retention.returned} of ${retention.eligible} eligible newcomers returned within three meetings.`,reason:'A welcome activity is a proposed experiment to address return visits; its effect has not been measured in this dataset.',confidence:confidence(retention.eligible),source:'calculate_retention'});
if(!recommendations.length)recommendations.push({title:rows.length<RULES.comparisons?'Keep recording meetings consistently.':'Try one change and track what happens.',evidence:`${rows.length} meetings are available. No compared setup has enough repeated examples to support a clear positive recommendation.`,reason:'Keep the other details similar and compare the next few meetings. Add meeting formats and promotion details if they are missing.',confidence:confidence(rows.length),source:'summarize_dataset'});
return{sampleSize:rows.length,recommendations:recommendations.slice(0,4),suggestedSetup:Object.fromEntries(recommendations.filter(r=>r.field).map(r=>[r.field,r.value])),warnings:['Suggested setups combine separate observational comparisons; the exact combination may not have been tried before. Promotion lead-time advice appears only when recorded lead times support a comparison.']}}
